# 65: Descriptive counts for the defence-pact network (triads, large alliances, dyads in no triad). Run with ALLIANCE_DEF=defense.
suppressMessages({ library(dplyr); library(readr); library(tidyr); library(igraph) })

source("scripts/38_hazard_panel_lib.R")
st <- base_signed() %>% filter(year >= 1816, year <= 2012) %>% distinct(year, lo, hi, .keep_all = TRUE)
tri <- bind_rows(lapply(sort(unique(st$year)), function(yr) { e <- st[st$year == yr, ]; if (nrow(e) < 3) return(NULL)
  g <- graph_from_data_frame(data.frame(a = as.character(e$lo), b = as.character(e$hi)), directed = FALSE); tr <- igraph::triangles(g); if (length(tr) == 0) return(NULL)
  tm <- matrix(V(g)$name[tr], ncol = 3, byrow = TRUE); key <- function(x, y) paste(pmin(as.numeric(x), as.numeric(y)), pmax(as.numeric(x), as.numeric(y)))
  sgn <- setNames(e$sign, key(e$lo, e$hi)); p <- sgn[key(tm[,1], tm[,2])] * sgn[key(tm[,1], tm[,3])] * sgn[key(tm[,2], tm[,3])]
  tibble(year = yr, n = length(p), unbal = sum(p < 0)) }))
sink("results/defence_descriptives_output.txt", split = TRUE)
cat(sprintf("Closed triad-years: %d, unbalanced: %d (%.1f%%)\n", sum(tri$n), sum(tri$unbal), 100 * sum(tri$unbal) / sum(tri$n)))
al <- read_csv("raw/alliances/version4.1_csv/alliance_v4.1_by_dyad_yearly.csv", show_col_types = FALSE) %>% filter(defense == 1) %>% mutate(lo = pmin(ccode1, ccode2), hi = pmax(ccode1, ccode2))
mem <- read_csv("raw/alliances/version4.1_csv/alliance_v4.1_by_member.csv", show_col_types = FALSE); size <- mem %>% group_by(version4id) %>% summarise(n_mem = n_distinct(ccode), .groups = "drop")
a2 <- al %>% left_join(size, by = "version4id") %>% filter(year >= 1816, year <= 2012) %>% group_by(year, lo, hi) %>% summarise(min_n = min(n_mem), .groups = "drop")
cat(sprintf("Allied dyad-years (defence pacts) 1816-2012: %d; covered by smallest alliance with >=8 members: %.1f%%\n", nrow(a2), 100 * mean(a2$min_n >= 8)))
big <- al %>% left_join(size, by = "version4id") %>% filter(n_mem >= 8) %>% distinct(version4id); cat("Distinct defence pacts with >=8 members:", nrow(big), "\n")
d0 <- build_panel(base_signed(), "")
x <- d0 %>% filter(!is.na(dep), !is.na(mut), !is.na(cap))
cat(sprintf("Dispute-years in analysis sample in no closed triad: %.1f%%; alliance-years: %.1f%%\n", 100 * mean(!x$any_tri[x$sign == -1]), 100 * mean(!x$any_tri[x$sign == 1])))
z <- function(v) as.numeric(scale(v)); library(sandwich); library(lmtest)
for (sg in c(-1, 1)) { s <- x %>% filter(sign == sg, any_tri) %>% mutate(z_dep = z(dep), z_mut = z(mut), z_cap = z(cap), l_dur = log(dur), l_unbal = log1p(n_unbal), l_bal = log1p(n_bal))
  m <- glm(flip_i ~ z_dep + z_mut + z_cap + l_dur + l_unbal + l_bal, s %>% mutate(flip_i = as.integer(flip)), family = binomial); ct <- coeftest(m, vcov = vcovCL(m, cluster = s$dyad))
  cat(sprintf("%s in >=1 triad only: larger share %.3f (se %.3f, p=%.4f) N=%d events=%d\n", ifelse(sg == -1, "Disputes", "Alliances"), ct["z_dep",1], ct["z_dep",2], ct["z_dep",4], nobs(m), sum(s$flip))) }
for (sg in c(-1, 1)) { s <- x %>% filter(sign == sg) %>% mutate(z_dep = z(dep), z_mut = z(mut), z_cap = z(cap), l_dur = log(dur), l_unbal = log1p(n_unbal), l_bal = log1p(n_bal), flip_i = as.integer(flip))
  m <- glm(flip_i ~ z_dep * (l_unbal + l_bal) + z_mut + z_cap + l_dur, s, family = binomial); ct <- coeftest(m, vcov = vcovCL(m, cluster = s$dyad))
  cat(sprintf("%s interactions: x U %.3f (se %.3f, p=%.4f) | x B %.3f (se %.3f, p=%.4f)\n", ifelse(sg == -1, "Disputes", "Alliances"), ct["z_dep:l_unbal",1], ct["z_dep:l_unbal",2], ct["z_dep:l_unbal",4], ct["z_dep:l_bal",1], ct["z_dep:l_bal",2], ct["z_dep:l_bal",4])) }
cat(sprintf("Alliance-years (signed, 1816-2011) %d; in analysis sample %d\n", sum(d0$sign == 1), sum(x$sign == 1)))
cat(sprintf("Dispute-years %d (4,321 expected); in analysis sample %d\n", sum(d0$sign == -1), sum(x$sign == -1)))
sink()
